ALTER TABLE loading_orders DROP CONSTRAINT loading_orders_workflow_state_check;
ALTER TABLE loading_orders ADD CONSTRAINT loading_orders_workflow_state_check CHECK(workflow_state IN('PENDING','REJECTED','READY','DEPARTED_PENDING','DEPARTED_CORRECTION','OUTBOUND','CANCELLED'));
CREATE OR REPLACE FUNCTION v32_inventory_state(physical text,occupied boolean,workflow text,loading text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN physical='OUTBOUND' THEN 'OUTBOUND' WHEN physical IS NOT NULL AND physical<>'IN_STOCK' THEN 'OTHER_HISTORY' WHEN workflow IN('READY','DEPARTED_PENDING','DEPARTED_CORRECTION') OR loading='LOADED' THEN 'LOADED_PENDING' WHEN workflow='PENDING' OR loading='DRAFT' THEN 'LOADING_ASSIGNED' WHEN occupied THEN 'PREPARATION_LOCKED' ELSE 'AVAILABLE' END $$;
CREATE OR REPLACE FUNCTION v32_state_label(code text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE code WHEN 'AVAILABLE' THEN '可用库存' WHEN 'PREPARATION_LOCKED' THEN '备货锁定' WHEN 'LOADING_ASSIGNED' THEN '已分配装车' WHEN 'LOADED_PENDING' THEN '已装车待正式出库' WHEN 'OUTBOUND' THEN '已正式出库' WHEN 'OTHER_HISTORY' THEN '已调整移出' END $$;
CREATE OR REPLACE FUNCTION v32_snapshot_state(s jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN s->>'inventory_state_code'='AVAILABLE' AND coalesce((s->>'pending_adjustment')::boolean,false) THEN 'PREPARATION_LOCKED' ELSE coalesce(s->>'inventory_state_code',v32_inventory_state(s->>'physical_status',(s->>'reservation_id' IS NOT NULL AND coalesce(s->>'lot_workflow_state','')<>'CANCELLED') OR s->>'sample_status'='SAMPLING' OR coalesce((s->>'pending_adjustment')::boolean,false),s->>'loading_workflow_state',CASE WHEN s->>'loading_status' IN('DRAFT','LOADED') THEN s->>'loading_status' END)) END $$;
